	[TestCaseSource(nameof(Fixtures))]
	public void Golden_snapshots_match_the_checked_in_bytes(string fixtureName, object value)
	{
		var expected = ReadFixture(fixtureName);

		Assert.Multiple(() =>
		{
			Assert.That(Serialize(value), Is.EqualTo(expected), "Serializing the built object.");

			var roundTripped = DeserializeThenReserialize(value, expected);
			Assert.That(roundTripped, Is.EqualTo(expected), "Deserializing the fixture then re-serializing.");
		});
	}

	/// <summary>
	/// Turns "covers every core construct" into a check that cannot silently rot. Walks every public
	/// instance property reachable from <see cref="UiTree" />, <see cref="UiPatch" />,
	/// <see cref="UiEvent" /> and <see cref="UiCapabilities" /> to find the wire record types a real
	/// tree, patch, event or capabilities payload can contain, then checks that every one of those
	/// types actually appears somewhere in <see cref="Fixtures" />'s object graphs. A namespace sweep
	/// would fail on day one, since <c>UiNegotiationResult</c> and <c>UiPatchOutcome</c> are
	/// computation results that never appear inside a tree, a patch or an event.
	/// </summary>
	[Test]
	public void Every_wire_record_appears_in_at_least_one_golden_fixture()
	{
		var reachable = ReachableWireTypes();
		var covered = CoveredTypes();

		Assert.That(reachable,
			Is.SubsetOf(covered),
			$"Missing from a golden fixture: {string.Join(", ", reachable.Except(covered).Select(t => t.Name))}");
	}

	private static HashSet<Type> ReachableWireTypes()
	{
		var roots = new[] { typeof(UiTree), typeof(UiPatch), typeof(UiEvent), typeof(UiCapabilities) };
		var visited = new HashSet<Type>();
		var queue = new Queue<Type>(roots);

		while (queue.Count > 0)
		{
			var type = queue.Dequeue();
			if (!IsWireRecordType(type) || !visited.Add(type))
			{
				continue;
			}

			foreach (var property in type.GetProperties())
			{
				foreach (var candidate in UnwrapPropertyTypes(property.PropertyType))
				{
					if (IsWireRecordType(candidate))
					{
						queue.Enqueue(candidate);
					}
				}
			}
		}

		return visited;
	}

	private static IEnumerable<Type> UnwrapPropertyTypes(Type propertyType)
	{
		var underlying = Nullable.GetUnderlyingType(propertyType) ?? propertyType;

		if (underlying.IsGenericType)
		{
			foreach (var argument in underlying.GetGenericArguments())
			{
				yield return argument;
			}
		}

		yield return underlying;
	}

	private static bool IsWireRecordType(Type type)
		=> type.Namespace is not null &&
			type.Namespace.StartsWith("MacroDeck.Ui.Model", StringComparison.Ordinal) &&
			type.IsSealed &&
			!type.IsEnum &&
			type != typeof(UiNegotiationResult) &&
			type != typeof(UiPatchOutcome);

	private static HashSet<Type> CoveredTypes()
	{
		var covered = new HashSet<Type>();
		var pending = new Queue<object>(Fixtures().Select(testCase => testCase.Arguments[1]!));

		while (pending.Count > 0)
		{
			var instance = pending.Dequeue();
			var type = instance.GetType();

			if (!IsWireRecordType(type) || !covered.Add(type))
			{
				continue;
			}

			foreach (var property in type.GetProperties())
			{
				var value = property.GetValue(instance);
				foreach (var child in FlattenValues(value))
				{
					pending.Enqueue(child);
				}
			}
		}

		return covered;
	}

	private static IEnumerable<object> FlattenValues(object? value)
	{
		switch (value)
		{
			case null:
				yield break;
			case string or JsonElement:
				yield break;
			case System.Collections.IDictionary dictionary:
				foreach (var entryValue in dictionary.Values)
				{
					if (entryValue is not null)
					{
						yield return entryValue;
					}
				}

				break;
			case System.Collections.IEnumerable enumerable:
				foreach (var item in enumerable)
				{
					if (item is not null)
					{
						yield return item;
					}
				}

				break;
			default:
				yield return value;
				break;
		}
	}

	private static string Serialize(object value) => value switch
	{
		UiNode node => UiCanonicalJson.Serialize(node),
		UiTree tree => UiCanonicalJson.Serialize(tree),
		UiSurface surface => UiCanonicalJson.Serialize(surface),
		UiEvent uiEvent => UiCanonicalJson.Serialize(uiEvent),
		UiPatch patch => UiCanonicalJson.Serialize(patch),
		UiResource resource => UiCanonicalJson.Serialize(resource),
		UiCapabilities capabilities => UiCanonicalJson.Serialize(capabilities),
		_ => throw new ArgumentOutOfRangeException(nameof(value)),
	};

	private static string DeserializeThenReserialize(object value, string json) => value switch
	{
		UiNode => Serialize(JsonSerializer.Deserialize<UiNode>(json, UiCanonicalJson.Options)!),
		UiTree => Serialize(JsonSerializer.Deserialize<UiTree>(json, UiCanonicalJson.Options)!),
		UiSurface => Serialize(JsonSerializer.Deserialize<UiSurface>(json, UiCanonicalJson.Options)!),
		UiEvent => Serialize(JsonSerializer.Deserialize<UiEvent>(json, UiCanonicalJson.Options)!),
		UiPatch => Serialize(JsonSerializer.Deserialize<UiPatch>(json, UiCanonicalJson.Options)!),
		UiResource => Serialize(JsonSerializer.Deserialize<UiResource>(json, UiCanonicalJson.Options)!),
		UiCapabilities => Serialize(JsonSerializer.Deserialize<UiCapabilities>(json, UiCanonicalJson.Options)!),
		_ => throw new ArgumentOutOfRangeException(nameof(value)),
	};

